import{z as o,x as d,o as e,c as s,q as n,j as B,D as E,d as r,s as l,S as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"股利信号","description":"","frontmatter":{"title":"股利信号","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/dividend-signaling.md","filePath":"econ/dividend-signaling.md","lastUpdated":1791063341000}'),A={name:"econ/dividend-signaling.md"};function p(c,a,h,m,_,D){const i=d("Mermaid");return e(),s("div",null,[a[2]||(a[2]=n('<h1 id="股利信号" tabindex="-1">股利信号 <a class="header-anchor" href="#股利信号" aria-label="Permalink to &quot;股利信号&quot;">​</a></h1><div class="epigraph"><p>现金股利之所以能说话，是因为它贵：差的类型模仿不起同样的派息，于是派息把持久盈利从便宜的声明里分离出来。</p><footer>—— Bhattacharya, Imperfect Information, Dividend Policy, and the Bird in the Hand Fallacy, Bell Journal of Economics, 1979；Miller and Rock, Dividend Policy under Asymmetric Information, Journal of Finance, 1985</footer></div><p><a href="/econ/dividend-fcf">上一课</a>在 MM 1961 无关性之上加上 Jensen 的自由现金流：派息把现金逼出企业。本课缺口是信息：投资与代理都给定之后，为什么还要派——因为经理知道盈利，市场不知道。不重做自制股利，不把回购提前写成主线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>MM 世界里股利可自制，不传递新信息。Lintner 平滑已经暗示经理把股利当持久盈利的承诺。缺口是把这句话收成信号均衡，与 <a href="/econ/spence-signaling">Spence</a> 同构：信号必须对差类型更贵。Bhattacharya（1979）让派息的代价来自外部融资的交易成本（或税收）：好企业预期现金流高，承诺高股利后较少真的去借贵的钱；差企业模仿会经常踩到发行成本。Miller 与 Rock（1985）让股利直接揭示当前盈利：投资加股利加发行必须对上资金来源，多派就是少投资或少留的会计身份，市场从派息反推被隐瞒的盈余。</p><p>两种技术不要混成一句「投资者喜欢支票」。一种是分离均衡里的昂贵行动，一种是会计身份加信息不对称下的推断。</p><p><span class="marginnote">直觉类比：高股利和「读名校」是同一种证明术。文凭能证明能力，不是因为课程有用，而是对能力差的人读下来太痛苦；同理，派息能证明盈利，不是因为股东爱现金，而是对盈利差的企业，发股利意味着频繁去借昂贵的钱来补窟窿——模仿的成本天生更高。</span></p><p><span class="marginnote">信号要烧真资源或放弃真投资。口头「我们很好」太便宜。Bird-in-hand 不是本课：那是把股利当风险更低的现金流，Bhattacharya 标题里已经标成谬误。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Bhattacharya：类型是预期盈利，行动是承诺的股利。成本来自为兑现股利而进行的昂贵外部融资。单交叉成立则高类型选高股利。Miller–Rock：经理先看到当期盈余，再选股利与投资；外部人只看到股利。欧拉式的一阶条件让股利成为盈余的充分统计（在他们的设定下），公告超常收益来自修正盈余，而不是来自「现金比资本利得好」。</p>',10)),(e(),B(t,null,{default:E(()=>[l(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRIV%5B%22%E7%BB%8F%E7%90%86%E7%9F%A5%E9%81%93%E7%9B%88%E5%88%A9%22%5D%20--%3E%20SIG%5B%22%E6%B4%BE%E6%81%AF%E4%BD%9C%E4%B8%BA%E8%A1%8C%E5%8A%A8%22%5D%0A%20%20SIG%20--%3E%20BH%5B%22Bhattacharya%3A%20%E5%85%91%E7%8E%B0%E6%88%90%E6%9C%AC%E5%88%86%E7%A6%BB%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20SIG%20--%3E%20MR%5B%22Miller-Rock%3A%20%E8%B5%84%E9%87%91%E8%BA%AB%E4%BB%BD%E5%8F%8D%E6%8E%A8%E7%9B%88%E4%BD%99%22%5D%0A%20%20FCF%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E5%90%90%E5%87%BA%E8%87%AA%E7%94%B1%E7%8E%B0%E9%87%91%E6%B5%81%22%5D%20--%3E%20OTHER%5B%22%E4%BB%A3%E7%90%86%2C%20%E4%B8%8D%E6%98%AF%E4%BF%A1%E5%8F%B7%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<p>代理与信号可以同时真：成熟企业既有 FCF 问题，又有要说的私有信息。本课只补信息刀，以免股利课序变成万能袋。</p><h3 id="下调为何疼" tabindex="-1">下调为何疼 <a class="header-anchor" href="#下调为何疼" aria-label="Permalink to &quot;下调为何疼&quot;">​</a></h3><p>Lintner 平滑在信号里是均衡策略：下调被读成类型变差，于是用留存当缓冲，只把持久部分定为股利。这与无关性不打架——摩擦是信息，不是股东不能自制。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是逆向选择下的分离。好类型选贵行动，差类型觉得贵得不划算。代价必须落在现金流上：税、发行成本、或放弃的投资。Miller–Rock 的机制更会计：外部人知道预算约束，不知道约束里的哪一项是私有盈余，于是把可观察的股利当充分统计。两种机制都要求市场半强式处理<strong>公告</strong>：价格在派息声明时跳，正是 <a href="/econ/emh">EMH</a> 后课要管的那一层，本课不检验事件窗口。</p>',5)),(e(),B(t,null,{default:E(()=>[l(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E7%A7%81%E6%9C%89%E7%B1%BB%E5%9E%8B%3A%20%E9%A2%84%E6%9C%9F%E7%9B%88%E5%88%A9%E9%AB%98%E6%88%96%E4%BD%8E%22%5D%20--%3E%20CHOICE%5B%22%E6%89%BF%E8%AF%BA%E8%82%A1%E5%88%A9%E6%B0%B4%E5%B9%B3%22%5D%0A%20%20CHOICE%20--%3E%20HIGH%5B%22%E6%B4%BE%E9%AB%98%E8%82%A1%E5%88%A9%22%5D%0A%20%20HIGH%20--%3E%20G%5B%22%E5%A5%BD%E7%B1%BB%E5%9E%8B%3A%20%E7%8E%B0%E9%87%91%E6%B5%81%E8%B6%B3%2C%20%E5%85%91%E7%8E%B0%E4%BE%BF%E5%AE%9C%22%5D%0A%20%20HIGH%20--%3E%20B%5B%22%E5%B7%AE%E7%B1%BB%E5%9E%8B%3A%20%E9%9C%80%E9%A2%91%E7%B9%81%E8%B4%B5%E4%BB%B7%E8%9E%8D%E8%B5%84%E8%A1%A5%E7%AA%9F%E7%AA%BF%22%5D%0A%20%20B%20--%3E%20NOTIM%5B%22%E6%A8%A1%E4%BB%BF%E4%B8%8D%E5%88%92%E7%AE%97%3A%20%E9%80%80%E5%9B%9E%E4%BD%8E%E8%82%A1%E5%88%A9%22%5D%0A%20%20G%20--%3E%20SEP%5B%22%E9%AB%98%E8%82%A1%E5%88%A9%E6%88%90%E4%B8%BA%E5%A5%BD%E7%B1%BB%E5%9E%8B%E7%9A%84%E5%8F%AF%E9%9D%A0%E5%90%8D%E7%89%87%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n('<p><span class="marginnote">「分离均衡」翻译成日常话：好类型和差类型最后做了<strong>不同</strong>的选择，市场只要看选择就能认出类型。与之相对的是「混同均衡」——两类做一样的事，观察白费。信号模型要找的正是让两类自动分开的成本线：成本太低大家都发，太高没人发，中等才分离。</span></p><p><span class="marginnote">Miller and Rock, <em>JF</em> 1985。意外股利与意外盈余在会计上连着；把股利反应全部叫成「喜欢分红偏好」，是把推断误读成效用。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把高股利写成好公司定理：成长约束下高股利可能是少投资，信号与代理会给出相反的福利。也不要在此跑公告超额表——事件研究在量化栏或后课 EMH，本栏只钉均衡。下一课 <a href="/econ/share-repurchase">股票回购</a>问同一信号能否用回购更便宜地发送，以及它如何替代现金股利。</p><p><span class="marginnote">初学者容易以为企业「削减股利省钱」是精明的财务操作。在信号均衡里，削减股利会被市场读成「经理的私有盈余变差了」，股价常常应声下跌——这正是 Lintner 观察到的经理宁可留缓冲也不轻易减息的原因。省下的现金买不回被改坏的类型标签。</span></p><p>后课默认：股利可以是昂贵信号或盈余的会计推断；MM 无关性在信息对称时仍是基准。自由现金流是另一条理由，不要互相吞并。</p><p>税收差会改变信号成本，本课不展开税码。强式失败（经理有私人信息）是信号的前提，与半强式定价公告可以并存。</p><p>Bird-in-hand 把股利当更安全的现金流，在 MM 下不成立：企业少派可以少发股，股东风险来自资产，不来自信封。Bhattacharya 用发行成本造分离，恰恰是为了不靠那条谬误。</p><p>回购下一课问：同一笔现金若以买回股份的形式离开，分离是否还成立、承诺是否变软。本课先把现金股利的信号技术钉死。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>股利能说话，因为它贵或因为它钉住资金来源身份。</li><li>Bhattacharya：兑现成本分离类型；Miller–Rock：派息反推盈余。</li><li>代理吐出现金与信号揭示类型是两条理由，不是一句偏好公理。</li><li>Bird-in-hand 不是本课；信号要烧真资源或放弃真投资。</li><li>下一课回购问同一现金能否用更软的承诺发送。</li><li>半强式处理公告；本课不跑事件窗口。</li><li>Lintner 平滑是均衡缓冲，不是对 MM 套利的否证。</li><li>强式失败是经理有私有信息；与半强式定价公告可以并存。</li><li>出处：Bhattacharya, <em>Bell Journal</em> 1979；Miller and Rock, <em>JF</em> 1985。</li></ul>',11))])}const g=o(A,[["render",p]]);export{u as __pageData,g as default};
